using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;
using MKSANCrud.Data;
using MKSANCrud.Models;
using MKSANCrud.Services.Clinica;
namespace MKSANCrud.Controllers;
[AllowAnonymous,Route("api/pep/fhir/R4"),EnableRateLimiting("webhooks"),ResponseCache(NoStore=true,Location=ResponseCacheLocation.None)]
public sealed class PepController(MKSANContext db,IConfiguration config,IClinicaClock clock):Controller {
 public override void OnActionExecuting(ActionExecutingContext c){var expected=config["PepIntegration:ApiKey"];var got=Request.Headers["X-CallMed-PEP-Key"].ToString();if(!config.GetValue("PepIntegration:Enabled",false)||string.IsNullOrEmpty(expected)||expected.Length<32){c.Result=StatusCode(503);return;}if(got.Length>512||!CryptographicOperations.FixedTimeEquals(SHA256.HashData(Encoding.UTF8.GetBytes(expected)),SHA256.HashData(Encoding.UTF8.GetBytes(got))))c.Result=Unauthorized();}
 JsonResult Fhir(object x)=>new(x,new System.Text.Json.JsonSerializerOptions(System.Text.Json.JsonSerializerDefaults.Web){DefaultIgnoreCondition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull}){ContentType="application/fhir+json"};
 async Task Audit(string type,int id,CancellationToken ct){db.AuditoriaEventos.Add(new(){Acao="Leitura PEP",Entidade=type,EntidadeId=id.ToString(),Descricao=(config["PepIntegration:ClientName"]??"PEP configurado")[..Math.Min((config["PepIntegration:ClientName"]??"PEP configurado").Length,200)],CriadoEm=DateTime.UtcNow});await db.SaveChangesAsync(ct);}
 [HttpGet("metadata")]public IActionResult Metadata()=>Fhir(new{resourceType="CapabilityStatement",status="active",date="2026-11-07",kind="instance",implementation=new{description="CallMed — integração administrativa"},software=new{name="CallMed",version="25.0.0"},fhirVersion="4.0.1",format=new[]{"json"},rest=new[]{new{mode="server",resource=new[]{"Patient","Practitioner","Appointment","Encounter","Location"}.Select(t=>new{type=t,interaction=new[]{new{code="read"}}})}}});
 [HttpGet("Patient/{id:int}")]public async Task<IActionResult> Patient(int id,CancellationToken ct){var p=await db.Pacientes.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.Ativo,ct);if(p==null)return NotFound();await Audit("Paciente",id,ct);return Fhir(new{resourceType="Patient",id=p.Id.ToString(),active=p.Ativo,name=new[]{new{use="official",text=p.Nome}},birthDate=p.DataNascimento?.ToString("yyyy-MM-dd")});}
 [HttpGet("Practitioner/{id:int}")]public async Task<IActionResult> Practitioner(int id,CancellationToken ct){var m=await db.Medicos.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.Ativo,ct);if(m==null)return NotFound();await Audit("Medico",id,ct);return Fhir(FhirPractitioner.Criar(m, config["PepIntegration:Fhir:IdentifierSystem"]));}
 [HttpGet("Location/{id:int}")]public async Task<IActionResult> Location(int id,CancellationToken ct){var s=await db.Salas.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct);if(s==null)return NotFound();await Audit("Sala",id,ct);return Fhir(new{resourceType="Location",id=s.Id.ToString(),name=s.Nome,status=s.Ativa?"active":"inactive"});}
 [HttpGet("Appointment/{id:int}")]public async Task<IActionResult> Appointment(int id,CancellationToken ct){var c=await db.Consultas.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct);if(c==null)return NotFound();var j=await db.Jornadas.AsNoTracking().SingleOrDefaultAsync(x=>x.ConsultaId==id,ct);var start=clock.ConverterParaUtc(c.Data.Date.Add(TimeSpan.Parse(c.Horario)));await Audit("Consulta",id,ct);return Fhir(new{resourceType="Appointment",id=c.Id.ToString(),status=c.Status switch{ConsultaStatus.Cancelada=>"cancelled",ConsultaStatus.Realizada=>"fulfilled",ConsultaStatus.Ausente=>"noshow",ConsultaStatus.Pendente=>"pending",_=>"booked"},start=start.ToString("o"),end=start.AddMinutes(j?.Duracao??c.DuracaoMinutos).ToString("o"),participant=new[]{new{actor=new{reference="Patient/"+c.PacienteId},status="accepted"},new{actor=new{reference="Practitioner/"+c.MedicoId},status="accepted"}}});}
 [HttpGet("Encounter/{id:int}")]public async Task<IActionResult> Encounter(int id,CancellationToken ct){var j=await db.Jornadas.AsNoTracking().Include(x=>x.Consulta).SingleOrDefaultAsync(x=>x.ConsultaId==id,ct);if(j==null)return NotFound();await Audit("Jornada",id,ct);return Fhir(new{resourceType="Encounter",id=id.ToString(),status=j.FimEm!=null?"finished":j.InicioEm!=null?"in-progress":j.ChegadaEm!=null?"arrived":"planned",@class=new{system="http://terminology.hl7.org/CodeSystem/v3-ActCode",code=j.Tele?"VR":"AMB"},subject=new{reference="Patient/"+j.Consulta.PacienteId},appointment=new[]{new{reference="Appointment/"+id}},period=j.InicioEm==null?null:new{start=j.InicioEm?.ToString("o"),end=j.FimEm?.ToString("o")}});}
}
